  'Create an account, open Creator Studio, complete your channel profile, then upload or organize videos from your dashboard.' => 'ສ້າງບັນຊີ, ເປີດ Creator Studio, ເຮັດສໍາເລັດໂປຣໄຟລ໌ຊ່ອງຂອງທ່ານ, ຈາກນັ້ນອັບໂຫຼດ ຫຼືຈັດລະບຽບວິດີໂອຈາກ dashboard ຂອງທ່ານ.',
