  'Creator profile pages, subscriptions, community posts, comments, and playlists are part of the same account and content system.' => 'ໜ້າໂປຣໄຟລ໌ຜູ້ສ້າງ, ການສະໝັກໃຊ້, ໂພສຊຸມຊົນ, ຄຳເຫັນ ແລະລາຍການຫຼິ້ນແມ່ນສ່ວນໜຶ່ງຂອງລະບົບບັນຊີ ແລະເນື້ອຫາດຽວກັນ.',
  'Creator publishing' => 'ການເຜີຍແຜ່ຜູ້ສ້າງ',
  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'ການຈັດການເນື້ອຫາ Creator Studio ໃຊ້ຮູບແບບການເບິ່ງເຫັນດຽວກັນ: ສາທາລະນະ, ບໍ່ມີລາຍຊື່ ຫຼືສ່ວນຕົວ. ວິ​ດີ​ໂອ​ທີ່​ກໍາ​ນົດ​ເວ​ລາ​ການ​ນໍາ​ໃຊ້​ການ​ສັງ​ເກດ​ເຫັນ​ທີ່​ຮ້ອງ​ຂໍ​ຫຼັງ​ຈາກ​ການ​ປ່ອຍ​.',
  'Creator tools' => 'ເຄື່ອງມືຜູ້ສ້າງ',
  'Creator uploads' => 'ອັບໂຫຼດຜູ້ສ້າງ',
  'Creators can upload videos, manage visibility, add thumbnails and captions, publish scheduled content, review their library, and track content from Creator Studio.' => 'ຜູ້ສ້າງສາມາດອັບໂຫລດວິດີໂອ, ຈັດການການເບິ່ງເຫັນ, ເພີ່ມຮູບຕົວຢ່າງ ແລະຄຳບັນຍາຍ, ເຜີຍແຜ່ເນື້ອຫາທີ່ກຳນົດເວລາໄວ້, ກວດເບິ່ງຫ້ອງສະໝຸດຂອງເຂົາເຈົ້າ ແລະຕິດຕາມເນື້ອຫາຈາກ Creator Studio.',
  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'ຜູ້ສ້າງຕ້ອງໃຫ້ຊື່, ຄຳອະທິບາຍ, ໝວດໝູ່, ພາສາ, ຮູບຕົວຢ່າງ, ຄຳບັນຍາຍທີ່ຖືກຕ້ອງ, ການເບິ່ງເຫັນ ແລະການຕັ້ງຄ່າການກຳນົດເວລາ. ວິ​ດີ​ໂອ​ທີ່​ກໍາ​ນົດ​ເວ​ລາ​ບໍ່​ແມ່ນ​ສາ​ທາ​ລະ​ນະ​ຈົນ​ກ​່​ວາ​ທີ່​ກໍາ​ນົດ​ເວ​ລາ​ຂອງ​ເຂົາ​ເຈົ້າ​ແລະ​ການ​ປຸງ​ແຕ່ງ​ສໍາ​ເລັດ​ຜົນ​.',
  'curl --request GET \\\\ --url' => 'curl --request GET \\\\ --url',
  'Current upload categories' => 'ປະເພດການອັບໂຫລດປັດຈຸບັນ',
  'Data is used to authenticate users, publish and process content, show videos and channels, personalize account preferences, prevent abuse, support moderation, provide admin analytics, and keep creator and viewer features working.' => 'ຂໍ້ມູນຖືກໃຊ້ເພື່ອພິສູດຢືນຢັນຜູ້ໃຊ້, ເຜີຍແຜ່ ແລະປະມວນຜົນເນື້ອຫາ, ສະແດງວິດີໂອ ແລະຊ່ອງຕ່າງໆ, ປັບແຕ່ງການຕັ້ງຄ່າບັນຊີສ່ວນຕົວ, ປ້ອງກັນການລ່ວງລະເມີດ, ສະໜັບສະໜູນການເບິ່ງແຍງກວດກາ, ສະໜອງການວິເຄາະຜູ້ເບິ່ງແຍງ ແລະຮັກສາຄຸນສົມບັດຂອງຜູ້ສ້າງ ແລະຜູ້ຊົມໃຫ້ເຮັດວຽກ.',
