  'No upload categories are configured.' => 'ບໍ່ມີປະເພດການອັບໂຫລດໃດຖືກຕັ້ງຄ່າ.',
  'Non-refundable cases' => 'ກໍລະນີທີ່ບໍ່ສາມາດຄືນເງິນໄດ້',
