  'Not provided' => 'ບໍ່ໄດ້ສະໜອງໃຫ້',
  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'ທີ່​ຢູ່​ຕິດ​ຕໍ່​ທາງ​ການ​, ການ​ຕິດ​ຕໍ່​ການ​ອອກ​ໃບ​ບິນ​, ແລະ​ຊ່ອງ​ທາງ​ການ​ຊ່ວຍ​ເຫຼືອ​ພາຍ​ນອກ​ຄວນ​ຈະ​ໄດ້​ຮັບ​ການ​ຕັ້ງ​ຄ່າ​ໂດຍ​ຜູ້​ດູ​ແລ​ເວັບ​ໄຊ PlayHub ສໍາ​ລັບ​ການ​ນໍາ​ໃຊ້​ນີ້​. ຫນ້ານີ້ໂດຍເຈດຕະນາບໍ່ສະແດງທີ່ຢູ່ອີເມວທີ່ບໍ່ໄດ້ຮັບການຢືນຢັນ.',
  'On this page' => 'ໃນໜ້ານີ້',
  'Open Help Center' => 'ເປີດສູນຊ່ວຍເຫຼືອ',
  'Open settings' => 'ເປີດການຕັ້ງຄ່າ',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'ເປີດການຕັ້ງຄ່າ, ໄປທີ່ຄວາມປອດໄພ, ຈາກນັ້ນໃຊ້ລະຫັດຜ່ານ ຫຼືກ່ອງໂຕ້ຕອບສອງປັດໄຈ. ການຈັດສົ່ງແບບສອງປັດໃຈຮອງຮັບອີເມລ໌ ຫຼືໂທລະສັບເມື່ອຖືກຕັ້ງຄ່າ.',
  'Operational snapshot' => 'ພາບຖ່າຍການດໍາເນີນງານ',
  'Optional, but recommended' => 'ທາງເລືອກ, ແຕ່ແນະນໍາ',
  'Other' => 'ອື່ນໆ',
  'Partnerships, press, and platform operations.' => 'ການຮ່ວມມື, ຫນັງສືພິມ, ແລະການດໍາເນີນງານເວທີ.',
  'Payment help' => 'ການຊ່ວຍເຫຼືອການຈ່າຍເງິນ',
  'Platform' => 'ເວທີ',
  'Playback' => 'ຫຼິ້ນຄືນ',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'ຄວາມຄືບໜ້າການຫຼິ້ນ, ສະຖານະເບິ່ງພາຍຫຼັງ, ມັກ, ຄຳເຫັນ, ການສະໝັກໃຊ້, ການແຈ້ງເຕືອນ ແລະການວິເຄາະຜູ້ເບິ່ງແຍງລະບົບຈະຖືກເກັບໄວ້ໃນຖານຂໍ້ມູນເມື່ອເຊື່ອມໂຍງກັບຄຸນສົມບັດຂອງແພລດຟອມທີ່ຜ່ານການຮັບຮອງ.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'ການຫຼິ້ນຄືນ, ຄຳເຫັນ, ມັກ, ເບິ່ງພາຍຫຼັງ, ການສະໝັກໃຊ້, ການແຈ້ງເຕືອນ, ຂໍ້ຄວາມ, ລາຍການຫຼິ້ນ ແລະການຕັ້ງຄ່າພາສາແມ່ນມີໃຫ້ນຳໃຊ້ຜ່ານເມນູການນຳທາງຫຼັກ ແລະບັນຊີ.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub ເປັນແພລດຟອມວິດີໂອສຳລັບການອັບໂຫລດ, ເບິ່ງ, ກຳນົດເວລາ, ຈັດການ ແລະຄວບຄຸມເນື້ອຫາຜູ້ສ້າງຈາກບັນຊີດຽວ.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub ແມ່ນແພລະຕະຟອມວິດີໂອທີ່ເຮັດວຽກໃນການຕິດຕັ້ງນີ້, ສ້າງຂຶ້ນສໍາລັບຜູ້ສ້າງ, ຜູ້ຊົມ, ຊຸມຊົນ, ແລະຜູ້ປະກອບການເວທີ.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub ສະໜອງຊ່ອງຜູ້ສ້າງ, ອັບໂຫຼດວິດີໂອ, ການເຜີຍແຜ່ຕາມກຳນົດເວລາ, ການສະໝັກໃຊ້, ຄຳເຫັນ, ລາຍການຫຼິ້ນ, ເບິ່ງພາຍຫຼັງ, ໜ້າເນື້ອຫາສົດ ແລະເຄື່ອງມືບໍລິຫານຈາກເວທີດຽວ.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ໃຊ້ຄຸກກີ້ທີ່ຈຳເປັນ ແລະບ່ອນເກັບຂໍ້ມູນຂອງບຣາວເຊີສຳລັບການເຂົ້າສູ່ລະບົບ, ການພິສູດຢືນຢັນ API, CSRF/ພຶດຕິກຳຄວາມປອດໄພ, ການເລືອກພາສາ, ການເລືອກຮູບແບບສີສັນ, ສະຖານະເມນູບັນຊີ ແລະຄຸນສົມບັດອື່ນໆທີ່ຈຳເປັນເພື່ອໃຫ້ແອັບພລິເຄຊັນເຮັດວຽກໄດ້.',
  'playhub_language, theme' => 'playhub_language, ຫົວຂໍ້',
  'Popular questions' => 'ຄຳຖາມຍອດນິຍົມ',
