  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'ຄວາມເປັນສ່ວນຕົວ, ຄຸກກີ, ຄວາມປອດໄພຂອງບັນຊີ, ຂໍ້ຄວາມຊ່ວຍເຫຼືອ, ແລະຂໍ້ມູນການເບິ່ງແຍງແມ່ນຖືກຈັດການຜ່ານນະໂຍບາຍ ແລະບັນທຶກດ້ານຫຼັງທີ່ເຊື່ອມຕໍ່ກັບ PlayHub.',
  'Profile, login, security, and settings help.' => 'ໂປຼໄຟລ໌, ເຂົ້າສູ່ລະບົບ, ຄວາມປອດໄພ, ແລະການຕັ້ງຄ່າຊ່ວຍ.',
  'Profile, security, and preferences.' => 'ໂປຣໄຟລ໌, ຄວາມປອດໄພ ແລະການຕັ້ງຄ່າ.',
  'Public API route' => 'ເສັ້ນທາງ API ສາທາລະນະ',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'ຈຸດສິ້ນສຸດຂອງ JSON ສາທາລະນະລວມມີ /api/health ສໍາລັບສະຖານະການນຳໃຊ້ ແລະ /api/upload-options ສຳລັບໝວດໝູ່ການອັບໂຫລດ, ພາສາ, ຂີດຈຳກັດ, ຂະໜາດຊິ້ນສ່ວນ ແລະແທັກທີ່ກຳລັງເປັນທີ່ນິຍົມ.',
