  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'ການຈັດການການຄືນເງິນສໍາລັບຄຸນສົມບັດ PlayHub ທີ່ເສຍເງິນແມ່ນຂຶ້ນກັບບັນທຶກການເອີ້ນເກັບເງິນທີ່ແທ້ຈິງທີ່ຕິດຄັດມາກັບການນຳໃຊ້ນີ້.',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'ການຈັດການການຄືນເງິນແມ່ນຜູກມັດກັບບັນທຶກການເອີ້ນເກັບເງິນທີ່ແທ້ຈິງ ແລະການທົບທວນຄືນຂອງຜູ້ເບິ່ງແຍງລະບົບ. ຖ້າການເອີ້ນເກັບເງິນບໍ່ຖືກຕັ້ງຄ່າສຳລັບການນຳໃຊ້ນີ້, ບໍ່ມີຄ່າບໍລິການໃນເວທີທີ່ຈະຄືນເງິນ.',
