  'Search for answers...' => 'ຊອກຫາຄຳຕອບ...',
  'Search help articles, topics, or questions...' => 'ຊອກຫາບົດຄວາມຊ່ວຍເຫຼືອ, ຫົວຂໍ້, ຫຼືຄໍາຖາມ...',
  'Select a reason' => 'ເລືອກເຫດຜົນ',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'ເລືອກໜຶ່ງ ຫຼືຫຼາຍໄຟລ໌ວິດີໂອ, ໃສ່ລາຍລະອຽດທີ່ຕ້ອງການ, ເລືອກໝວດໝູ່ ແລະພາສາ, ເພີ່ມຮູບຕົວຢ່າງ, ເລືອກການເບິ່ງເຫັນ ແລະເຜີຍແຜ່. ໄຟລ໌ຂະຫນາດໃຫຍ່ຖືກອັບໂຫລດເປັນຕ່ອນກ່ອນທີ່ເຄື່ອງແມ່ຂ່າຍຈະເລີ່ມຕົ້ນການປຸງແຕ່ງ.',
  'Send a message and it will be saved for admins.' => 'ສົ່ງຂໍ້ຄວາມແລະມັນຈະຖືກບັນທຶກໄວ້ສໍາລັບຜູ້ເບິ່ງແຍງ.',
  'Send billing details to admin support for review.' => 'ສົ່ງລາຍລະອຽດການຮຽກເກັບເງິນໄປຫາຝ່າຍຊ່ວຍເຫຼືອຜູ້ເບິ່ງແຍງເພື່ອກວດສອບ.',
  'Send message' => 'ສົ່ງຂໍ້ຄວາມ',
  'Send order details through the refund popup.' => 'ສົ່ງລາຍລະອຽດການສັ່ງຊື້ຜ່ານປັອບອັບການຄືນເງິນ.',
  'Send us a message' => 'ສົ່ງຂໍ້ຄວາມຫາພວກເຮົາ',
  'Sending...' => 'ກຳລັງສົ່ງ...',
  'Server configured' => 'ເຊີບເວີຖືກຕັ້ງຄ່າ',
  'server records' => 'ບັນທຶກເຊີບເວີ',
  'Service operation' => 'ການດໍາເນີນງານການບໍລິການ',
  'session, token' => 'session, token',
  'Settings and login' => 'ການຕັ້ງຄ່າແລະເຂົ້າສູ່ລະບົບ',
  'Short summary' => 'ສະຫຼຸບສັ້ນ',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'ເຂົ້າສູ່ລະບົບ ແລະໃຊ້ການຕັ້ງຄ່າບັນຊີ, ໂປຣໄຟລ໌, ລະຫັດຜ່ານ, ການແຈ້ງເຕືອນ, ຄວາມເປັນສ່ວນຕົວ ແລະ ການຕັ້ງຄ່າຂອງຜູ້ສ້າງ. ບັນຫາການອັບໂຫລດ ແລະເນື້ອຫາຂອງຜູ້ສ້າງຄວນຮວມມີຊື່ວິດີໂອ, ຊ່ອງ, ໂປຣແກຣມທ່ອງເວັບ ແລະຄວາມຜິດພາດການປະມວນຜົນທີ່ສະແດງຢູ່ໃນໜ້າອັບໂຫລດ.',
  'Sign in for account support' => 'ເຂົ້າສູ່ລະບົບເພື່ອສະຫນັບສະຫນູນບັນຊີ',
  'Signed in' => 'ເຂົ້າສູ່ລະບົບ',
  'Start uploading' => 'ເລີ່ມການອັບໂຫລດ',
  'Still can’t find an answer?' => 'ຍັງ​ບໍ່​ສາ​ມາດ​ຊອກ​ຫາ​ຄໍາ​ຕອບ​?',
  'Stored for admins' => 'ເກັບຮັກສາໄວ້ສໍາລັບຜູ້ບໍລິຫານ',
  'Stores language, theme, and interface preferences.' => 'ເກັບຮັກສາພາສາ, ຮູບແບບສີສັນ ແລະການຕັ້ງຄ່າໃນການໂຕ້ຕອບ.',
  'Studio, playlists, analytics, channels.' => 'ສະຕູດິໂອ, ລາຍການຫຼິ້ນ, ການວິເຄາະ, ຊ່ອງ.',
  'Submit a billing or refund message to admin support.' => 'ສົ່ງໃບບິນ ຫຼືຂໍ້ຄວາມການຄືນເງິນໃຫ້ກັບການຊ່ວຍເຫຼືອຜູ້ເບິ່ງແຍງລະບົບ.',
  'Submit refund request' => 'ສົ່ງຄໍາຮ້ອງຂໍຄືນເງິນ',
  'Submit request' => 'ສົ່ງຄໍາຮ້ອງຂໍ',
  'Subscription cancellation' => 'ການຍົກເລີກການສະໝັກໃຊ້',
  'Support dashboard' => 'ຮອງຮັບ dashboard',
  'System status' => 'ສະຖານະລະບົບ',
  'Table' => 'ຕາຕະລາງ',
  'Taxonomies' => 'ການຈັດໝວດໝູ່',
  'Technical issue' => 'ບັນຫາດ້ານວິຊາການ',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'ບັນທຶກດ້ານວິຊາການສໍາລັບການເຊື່ອມໂຍງກັບ PlayHub API ປະຈຸບັນແລະຂັ້ນຕອນການອັບໂຫລດການເຮັດວຽກ.',
  'Tell us more about your question or request...' => 'ບອກພວກເຮົາເພີ່ມເຕີມກ່ຽວກັບຄໍາຖາມຫຼືຄໍາຮ້ອງຂໍຂອງທ່ານ ...',
  'Terms of Use' => 'ເງື່ອນໄຂການນໍາໃຊ້',
  'The configured' => 'ການ​ຕັ້ງ​ຄ່າ​',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ຫນ້ານັກພັດທະນາເຊື່ອມຕໍ່ກັບ backend Laravel ສົດ: ບັນຊີລາຍການເສັ້ນທາງ, ຈໍານວນຖານຂໍ້ມູນ, ຈໍາກັດການອັບໂຫລດ, ແລະ metadata ຂອງແພລະຕະຟອມຖືກໂຫລດຈາກ /api/developers.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Frontend ເກັບຮັກສາການຕັ້ງຄ່າເຊັ່ນ: ພາສາທີ່ເລືອກ, ຮູບແບບສີສັນ, ຄິວການຫຼິ້ນ, ເບິ່ງຄວາມຄືບຫນ້າ, ແລະສະຖານະການໂຕ້ຕອບເພື່ອໃຫ້ປະສົບການຍັງຄົງສອດຄ່ອງໃນທົ່ວການນໍາທາງຫນ້າແລະການໂຫຼດໃຫມ່.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'ວຽກການປະມວນຜົນ encodes renditions, ສ້າງຮູບຫຍໍ້ໃນເວລາທີ່ຈໍາເປັນ, ເກັບຮັກສາຄໍາບັນຍາຍ, ແລະຫມາຍວິດີໂອພ້ອມໃນເວລາທີ່ການປະມວນຜົນສໍາເລັດ. ວິດີໂອທີ່ກຳນົດເວລາໄວ້ໃນອະນາຄົດຍັງຄົງເປັນສ່ວນຕົວຈົນກວ່າຜູ້ກຳນົດເວລາຈະປ່ອຍພວກມັນອອກ.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'ລະບົບການອັບໂຫລດແມ່ນຮອງດ້ວຍຖານຂໍ້ມູນ, ຮອງຮັບໝວດໝູ່ ແລະພາສາຈາກ API, ປະມວນຜົນວິດີໂອທີ່ອັບໂຫຼດ, ຈັດເກັບຮູບຕົວຢ່າງ ແລະຄຳບັນຍາຍ, ແລະຮັກສາເນື້ອຫາທີ່ກຳນົດເວລາໄວ້ເປັນສ່ວນຕົວຈົນກ່ວາເວລາປ່ອຍອອກມາ.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'ໜ້ານີ້ອະທິບາຍວິທີທີ່ PlayHub ໃຊ້ຄຸກກີ້ ແລະບ່ອນເກັບຂໍ້ມູນຂອງບຣາວເຊີສຳລັບເຊດຊັນ, ຄວາມປອດໄພ, ຄວາມມັກ, ການຫຼິ້ນ ແລະຄຸນສົມບັດທີ່ຜ່ານການຮັບຮອງຄວາມຖືກຕ້ອງ.',
  'Ticket source' => 'ແຫຼ່ງປີ້',
  'Top content categories' => 'ປະເພດເນື້ອຫາສູງສຸດ',
  'Topic' => 'ຫົວຂໍ້',
  'Transaction / invoice' => 'ທຸລະກໍາ / ໃບເກັບເງິນ',
  'Transaction / invoice ID' => 'ID ທຸລະກໍາ / ໃບເກັບເງິນ',
  'Unable to send message.' => 'ບໍ່ສາມາດສົ່ງຂໍ້ຄວາມໄດ້.',
  'Unable to submit refund request.' => 'ບໍ່ສາມາດສົ່ງຄຳຮ້ອງຂໍຄືນເງິນໄດ້.',
  'Understanding admin support tickets' => 'ເຂົ້າໃຈປີ້ສະຫນັບສະຫນູນ admin',
  'Upload and processing help' => 'ອັບໂຫຼດ ແລະ ປະມວນຜົນການຊ່ວຍເຫຼືອ',
  'Upload chunks' => 'ອັບໂຫຼດຊິ້ນສ່ວນ',
  'Upload issues' => 'ບັນຫາການອັບໂຫລດ',
  'Upload languages' => 'ອັບໂຫລດພາສາ',
  'Upload limit' => 'ຈຳກັດການອັບໂຫລດ',
  'Upload options' => 'ຕົວເລືອກການອັບໂຫລດ',
  'Upload or processing' => 'ອັບໂຫຼດ ຫຼືປະມວນຜົນ',
  'Upload page' => 'ອັບໂຫຼດໜ້າ',
  'Upload pipeline' => 'ອັບໂຫລດທໍ່',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'ອັບໂຫຼດ, ເບິ່ງ, ຕິດຕາມ, ປານກາງ, ແລະສ້າງດ້ວຍຂໍ້ມູນ PlayHub ສົດ.',
  'Uploaded videos' => 'ວິດີໂອທີ່ອັບໂຫຼດ',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'ວິ​ດີ​ໂອ​ທີ່​ອັບ​ໂຫຼດ​ໄດ້​ຖືກ​ເຂົ້າ​ລະ​ຫັດ​ເປັນ​ການ​ແກ້​ໄຂ​ທີ່​ສາ​ມາດ​ຫຼິ້ນ​ໄດ້​. ເວລາປະມວນຜົນແມ່ນຂຶ້ນກັບຂະໜາດໄຟລ໌, ໄລຍະເວລາ, ການໂຫຼດຂອງເຊີບເວີ, ແລະສະຖານະຄິວ. ຫນ້າອັບໂຫລດແລະ Creator Studio ສະແດງສະຖານະການປະມວນຜົນທີ່ແທ້ຈິງຈາກບັນທຶກວິດີໂອ.',
  'Uploads, scheduling, and processing are available.' => 'ການອັບໂຫລດ, ການກຳນົດເວລາ, ແລະການປະມວນຜົນແມ່ນມີຢູ່.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'ໃຊ້ /api/videos, ຈຸດສິ້ນສຸດຂອງຊ່ອງ, ແລະເສັ້ນທາງທີ່ຮັບຮອງຄວາມຖືກຕ້ອງສໍາລັບຂັ້ນຕອນການເຮັດວຽກຂອງຜູ້ສ້າງ.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ໃຊ້ການດໍາເນີນການລາຍງານໃນຕົວສໍາລັບວິດີໂອແລະຄໍາຄິດຄໍາເຫັນເພື່ອໃຫ້ຜູ້ເບິ່ງແຍງໄດ້ຮັບການອ້າງອີງເນື້ອຫາທີ່ແນ່ນອນ. ຫນ້າ dashboard ຂອງຜູ້ເບິ່ງແຍງໃຊ້ຂໍ້ມູນຖານຂໍ້ມູນສົດສໍາລັບຜູ້ໃຊ້, ເນື້ອຫາ, ບົດລາຍງານ, ການສ້າງລາຍໄດ້, ການວິເຄາະ, ການສະຫນັບສະຫນູນ, ພາລະບົດບາດ, ແລະການຕັ້ງຄ່າລະບົບ.',
  'Use Contact Us' => 'ໃຊ້ຕິດຕໍ່ພວກເຮົາ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'ໃຊ້ JSON ສໍາລັບການຮ້ອງຂໍ API ປົກກະຕິແລະ FormData ສໍາລັບການອັບໂຫລດໄຟລ໌. ຢ່າຂ້າມຜ່ານການກວດສອບ: ໝວດໝູ່ ແລະພາສາແມ່ນ ID ຖານຂໍ້ມູນ, ການສະແດງຜົນຖືກຈຳກັດເປັນສາທາລະນະ, ບໍ່ມີລາຍຊື່, ຫຼືສ່ວນຕົວ, ແລະຄຳບັນຍາຍຍອມຮັບໄຟລ໌ SRT, VTT, ຫຼື TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'ໃຊ້ການຕັ້ງຄ່າເພື່ອອັບເດດໂປຣໄຟລ໌, ຄວາມປອດໄພ, ລະຫັດຜ່ານ, ການຈັດສົ່ງສອງປັດໃຈ, ອຸປະກອນ, ການຕັ້ງຄ່າ ແລະຕົວເລືອກການແຈ້ງເຕືອນຂອງທ່ານ. ຖ້າທ່ານບໍ່ສາມາດເຂົ້າເຖິງບັນຊີຂອງທ່ານໄດ້, ໃຫ້ໃຊ້ຂັ້ນຕອນການເຂົ້າສູ່ລະບົບແລະໃຫ້ອີເມວບັນຊີກັບຜູ້ເບິ່ງແຍງເວັບໄຊທ໌.',
  'Use the contact form' => 'ໃຊ້ແບບຟອມຕິດຕໍ່',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ໃຊ້ການດໍາເນີນການລາຍງານກ່ຽວກັບວິດີໂອ, ຄໍາເຫັນ, ແລະຂໍ້ຄວາມຊຸມຊົນເພື່ອໃຫ້ຜູ້ເບິ່ງແຍງໄດ້ຮັບການອ້າງອີງເນື້ອຫາທີ່ແນ່ນອນ.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'ໃຊ້ການດໍາເນີນການລາຍງານກ່ຽວກັບວິດີໂອ, ຄໍາເຫັນ, ແລະຂໍ້ຄວາມຊຸມຊົນໃນເວລາທີ່ເນື້ອຫາອາດຈະລະເມີດກົດລະບຽບເວທີ. ບົດລາຍງານເຫຼົ່ານີ້ຖືກຜູກມັດກັບບັນທຶກເນື້ອຫາທີ່ແທ້ຈິງແລະດີກ່ວາຂໍ້ຄວາມທົ່ວໄປເພາະວ່າຜູ້ບໍລິຫານສາມາດທົບທວນຄືນລາຍການທີ່ແນ່ນອນ.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'ໃຊ້ຊ່ອງ PlayHub ທີ່ຖືກຕ້ອງສໍາລັບການຊ່ວຍເຫຼືອບັນຊີ, ບົດລາຍງານເນື້ອຫາ, ບັນຫາດ້ານວິຊາການ, ແລະຄໍາຮ້ອງຂໍຂອງຜູ້ເບິ່ງແຍງລະບົບ.',
  'Video categories' => 'ໝວດໝູ່ວິດີໂອ',
  'Video for everyone. Built for creators and viewers.' => 'ວິດີໂອສໍາລັບທຸກຄົນ. ສ້າງຂຶ້ນຈາກຂໍ້ມູນເວທີທີ່ແທ້ຈິງ.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ການອັບໂຫລດວິດີໂອ, ການກຳນົດເວລາ, ຮູບຕົວຢ່າງ, ແລະບັນຫາການປະມວນຜົນ.',
  'Videos, thumbnails, captions, processing.' => 'ວິດີໂອ, ຮູບຕົວຢ່າງ, ຄຳບັນຍາຍ, ການປະມວນຜົນ.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ຜູ້ຊົມສາມາດຊອກຫາໝວດໝູ່, ຊອກຫາວິດີໂອ, ເບິ່ງເນື້ອຫາ, ຕິດຕາມຊ່ອງ, ບັນທຶກວິດີໂອໄວ້ເບິ່ງພາຍຫຼັງ, ສະແດງຄຳເຫັນ, ຮັບການແຈ້ງເຕືອນ ແລະຈັດການພາສາ ແລະການຕັ້ງຄ່າການຊ່ວຍເຂົ້າເຖິງໄດ້.',
  'Viewing and community help' => 'ການເບິ່ງແລະການຊ່ວຍເຫຼືອຊຸມຊົນ',
  'Waiting for backend endpoint inventory.' => 'ກຳລັງລໍຖ້າສິນຄ້າຄົງຄັງຈຸດສິ້ນສຸດດ້ານຫຼັງ.',
  'We’re here to help.' => 'ພວກເຮົາຢູ່ທີ່ນີ້ເພື່ອຊ່ວຍ.',
  'What is PlayHub?' => 'PlayHub ແມ່ນຫຍັງ?',
  'What PlayHub does' => 'ສິ່ງທີ່ PlayHub ເຮັດ',
  'Where do contact messages go?' => 'ຂໍ້ຄວາມຕິດຕໍ່ໄປໃສ?',
  'Why is my video still processing?' => 'ເປັນຫຍັງວິດີໂອຂອງຂ້ອຍຍັງປະມວນຜົນຢູ່?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'ແມ່ນແລ້ວ. ໃຊ້ຊ່ອງຂໍ້ມູນວັນທີ ແລະເວລາພື້ນເມືອງຢູ່ໃນໜ້າອັບໂຫລດ. backend ເກັບຮັກສາ scheduled_at, ປະມວນຜົນວິດີໂອ, ຮັກສາມັນເປັນສ່ວນຕົວໃນຂະນະທີ່ວັນທີໃນອະນາຄົດ, ແລະປ່ອຍມັນເມື່ອ Laravel scheduler ເຮັດວຽກຫຼັງຈາກເວລາທີ່ກໍານົດໄວ້.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'ແມ່ນແລ້ວ. ໃຊ້ຊ່ອງຂໍ້ມູນກໍານົດເວລາພື້ນເມືອງໃນການອັບໂຫລດ. backend ເກັບຮັກສາ scheduled_at ແລະປ່ອຍວິດີໂອຫຼັງຈາກການປະມວນຜົນເມື່ອເຖິງເວລາກໍານົດ.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'ທ່ານກຳລັງຊອກຫາແຂກ. ເຂົ້າສູ່ລະບົບເພື່ອເຂົ້າເຖິງເຄື່ອງມືສະເພາະບັນຊີ.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'ທ່ານຮັບຜິດຊອບຕໍ່ຂໍ້ມູນປະຈຳຕົວບັນຊີຂອງທ່ານ, ການເຄື່ອນໄຫວໂປຣໄຟລ໌, ເນື້ອຫາທີ່ອັບໂຫຼດ, ຄຳເຫັນ, ຂໍ້ຄວາມ, ແລະການກະທຳໃດໆຂອງຜູ້ສ້າງ ຫຼືຜູ້ເບິ່ງແຍງລະບົບທີ່ເຮັດຈາກບັນຊີຂອງທ່ານ. ໃຊ້ລະຫັດຜ່ານທີ່ເຂັ້ມແຂງແລະຮັກສາວິທີການຈັດສົ່ງສອງປັດໃຈໃນປະຈຸບັນ.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'ທ່ານ​ສາ​ມາດ​ລຶບ cookies ຂອງ​ຕົວ​ທ່ອງ​ເວັບ​ແລະ​ການ​ເກັບ​ຮັກ​ສາ​ໃນ​ທ້ອງ​ຖິ່ນ​ໃນ​ການ​ຕັ້ງ​ຄ່າ​ຂອງ​ຕົວ​ທ່ອງ​ເວັບ​ຂອງ​ທ່ານ​. ການລຶບລ້າງພື້ນທີ່ຈັດເກັບຂໍ້ມູນທີ່ຈໍາເປັນອາດເຮັດໃຫ້ເຈົ້າອອກຈາກລະບົບ, ຕັ້ງຄ່າພາສາ/ຮູບແບບສີສັນຄືນໃໝ່, ລຶບສະຖານະການຫຼິ້ນໃນເຄື່ອງອອກ, ແລະຮຽກຮ້ອງໃຫ້ເຈົ້າເຂົ້າສູ່ລະບົບອີກຄັ້ງ.',
  'You receive a response by email.' => 'ທ່ານໄດ້ຮັບຄໍາຕອບໂດຍອີເມລ໌.',
  'You’re in control' => 'ເຈົ້າຢູ່ໃນການຄວບຄຸມ',
  'Your choices' => 'ການເລືອກຂອງເຈົ້າ',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'ຂໍ້ຄວາມຂອງທ່ານຖືກບັນທຶກໄວ້ໂດຍກົງໃນ backend ເວັບໄຊທ໌ແລະປາກົດຢູ່ໃນ dashboard admin ພາຍໃຕ້ການສະຫນັບສະຫນູນ.',
  'Your support' => 'ສະຫນັບສະຫນູນຂອງທ່ານ',
  'Watch video' => 'ເບິ່ງວີດີໂອ',
  'Copy link' => 'ສຳເນົາລິ້ງ',
  'View creator' => 'ເບິ່ງຜູ້ສ້າງ',
  'Remove from playlist' => 'ເອົາອອກຈາກລາຍການຫຼິ້ນ',
  'Removing videos from playlists is not available here yet.' => 'ການ​ລຶບ​ວິ​ດີ​ໂອ​ອອກ​ຈາກ playlists ແມ່ນ​ຍັງ​ບໍ່​ມີ​ຢູ່​ທີ່​ນີ້​.',
  'Create New Playlist' => 'ສ້າງລາຍການຫຼິ້ນໃໝ່',
  'Organize your videos into a playlist' => 'ຈັດລະບຽບວິດີໂອຂອງທ່ານເຂົ້າໄປໃນລາຍການຫຼິ້ນ',
  'Playlist Name' => 'ຊື່ລາຍການຫຼິ້ນ',
  'e.g. Travel Vlogs 2025' => 'ຕົວຢ່າງ: Vlogs ການເດີນທາງ 2025',
  '(optional)' => '(ທາງເລືອກ)',
  'What’s this playlist about?' => 'ລາຍການຫຼິ້ນນີ້ກ່ຽວກັບຫຍັງ?',
  'Select Color' => 'ເລືອກສີ',
  'This color will represent your playlist' => 'ສີນີ້ຈະເປັນຕົວແທນຂອງລາຍການຫຼິ້ນຂອງທ່ານ',
  'Anyone can view this playlist' => 'ທຸກຄົນສາມາດເບິ່ງລາຍການຫຼິ້ນນີ້ໄດ້',
  'Only you can view this playlist' => 'ພຽງ​ແຕ່​ທ່ານ​ສາ​ມາດ​ເບິ່ງ playlist ນີ້​',
  'Anyone with the link can view' => 'ທຸກຄົນທີ່ມີລິ້ງສາມາດເບິ່ງໄດ້',
  'Add to Playlist' => 'ເພີ່ມໃສ່ລາຍການຫຼິ້ນ',
  'Add videos to this playlist now' => 'ເພີ່ມວິດີໂອໃສ່ລາຍການຫຼິ້ນນີ້ດຽວນີ້',
  'Search videos to add...' => 'ຊອກຫາວິດີໂອເພື່ອເພີ່ມ...',
  'selected' => 'ເລືອກ',
  'Clear' => 'ຈະແຈ້ງ',
  'Tip' => 'ເຄັດລັບ',
  'Use playlists to organize your content and make it easier for your audience to discover more videos.' => 'ໃຊ້ລາຍການຫຼິ້ນເພື່ອຈັດລະບຽບເນື້ອຫາຂອງທ່ານ ແລະເຮັດໃຫ້ມັນງ່າຍຂຶ້ນສຳລັບຜູ້ຊົມຂອງທ່ານໃນການຄົ້ນພົບວິດີໂອຫຼາຍຂຶ້ນ.',
  'Unable to create playlist.' => 'ບໍ່ສາມາດສ້າງລາຍການຫຼິ້ນໄດ້.',
  'public' => 'ສາທາລະນະ',
  'private' => 'ສ່ວນຕົວ',
  'unlisted' => 'ບໍ່ມີລາຍຊື່',
  'Your playlists' => 'ລາຍການຫຼິ້ນຂອງເຈົ້າ',
  'Create your first playlist to organize videos from your channel and saved library.' => 'ສ້າງລາຍການຫຼິ້ນທຳອິດຂອງທ່ານເພື່ອຈັດລະບຽບວິດີໂອຈາກຊ່ອງຂອງທ່ານ ແລະຫ້ອງສະໝຸດທີ່ບັນທຶກໄວ້.',
  'Loading playlists...' => 'ກຳລັງໂຫຼດລາຍການຫຼິ້ນ...',
  'No description has been added for this playlist yet.' => 'ບໍ່ມີການເພີ່ມຄຳອະທິບາຍສຳລັບລາຍການຫຼິ້ນນີ້ເທື່ອ.',
  'Updated' => 'ອັບເດດ',
  'Created' => 'ສ້າງແລ້ວ',
  'recently' => 'ເມື່ອບໍ່ດົນມານີ້',
