  'Video Import' => 'ວິດີໂອນໍາເຂົ້າ',
  'Enable importing videos from supported external providers.' => 'ເປີດໃຊ້ການນໍາເຂົ້າວິດີໂອຈາກຜູ້ໃຫ້ບໍລິການພາຍນອກທີ່ຮອງຮັບ.',
