  'Video import settings saved.' => 'ບັນທຶກການຕັ້ງຄ່າການນໍາເຂົ້າວິດີໂອແລ້ວ.',
  'Video import started.' => 'ການ​ນໍາ​ເຂົ້າ​ວິ​ດີ​ໂອ​ໄດ້​ເລີ່ມ​ຕົ້ນ​.',
  'This video import provider is disabled.' => 'ຜູ້ໃຫ້ບໍລິການນໍາເຂົ້າວິດີໂອນີ້ຖືກປິດໃຊ້ງານ.',
  'Video import provider is disabled.' => 'ຜູ້ໃຫ້ບໍລິການນໍາເຂົ້າວິດີໂອຖືກປິດໃຊ້ງານ.',
  'Direct imports must use a supported video file URL.' => 'ການນໍາເຂົ້າໂດຍກົງຈະຕ້ອງໃຊ້ URL ໄຟລ໌ວິດີໂອທີ່ຮອງຮັບ.',
  'Cannot open remote video URL.' => 'ບໍ່ສາມາດເປີດ URL ວິດີໂອທາງໄກໄດ້.',
  'Cannot prepare imported video file.' => 'ບໍ່ສາມາດກະກຽມໄຟລ໌ວິດີໂອທີ່ນໍາເຂົ້າໄດ້.',
  'Cannot read remote video file.' => 'ບໍ່ສາມາດອ່ານໄຟລ໌ວິດີໂອທາງໄກໄດ້.',
  'Imported video exceeds the maximum upload size.' => 'ວິດີໂອທີ່ນຳເຂົ້າມາເກີນຂະໜາດການອັບໂຫລດສູງສຸດ.',
  'Remote video file is empty.' => 'ໄຟລ໌ວິດີໂອທາງໄກຫວ່າງເປົ່າ.',
  'Video import downloader command is not configured.' => 'ຄໍາສັ່ງດາວໂຫຼດວິດີໂອນໍາເຂົ້າບໍ່ໄດ້ກໍານົດ.',
  'Downloader did not create an importable video file.' => 'ຕົວດາວໂຫລດບໍ່ໄດ້ສ້າງໄຟລ໌ວິດີໂອທີ່ນໍາເຂົ້າໄດ້.',
  'Import URL is invalid.' => 'ການນໍາເຂົ້າ URL ບໍ່ຖືກຕ້ອງ.',
  'Import URL must use HTTP or HTTPS.' => 'URL ທີ່ນໍາເຂົ້າຈະຕ້ອງໃຊ້ HTTP ຫຼື HTTPS.',
  'Import URL host is invalid.' => 'ເຈົ້າພາບ URL ທີ່ນໍາເຂົ້າບໍ່ຖືກຕ້ອງ.',
  'Import URL does not match the selected provider.' => 'URL ການນໍາເຂົ້າບໍ່ກົງກັບຜູ້ໃຫ້ບໍລິການທີ່ເລືອກ.',
  'Import URL host cannot be resolved.' => 'ການນໍາເຂົ້າ URL host ບໍ່ສາມາດແກ້ໄຂໄດ້.',
  'Import URL must resolve to a public host.' => 'ການນໍາເຂົ້າ URL ຕ້ອງແກ້ໄຂເປັນເຈົ້າພາບສາທາລະນະ.',
  'Unknown video import provider.' => 'ຜູ້ໃຫ້ບໍລິການນໍາເຂົ້າວິດີໂອທີ່ບໍ່ຮູ້ຈັກ.',
  'Saves a public video file URL and plays it from the original URL.' => 'ບັນທຶກ URL ໄຟລ໌ວິດີໂອສາທາລະນະ ແລະຫຼິ້ນມັນຈາກ URL ຕົ້ນສະບັບ.',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'ດຶງເອົາລາຍລະອຽດຂອງ YouTube ແລະຫຼິ້ນກັບເຄື່ອງຫຼິ້ນທີ່ຝັງຢູ່ໃນ YouTube.',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'ດຶງເອົາລາຍລະອຽດ Vimeo ແລະຫຼິ້ນກັບເຄື່ອງຫຼິ້ນ Vimeo ຝັງ.',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'ດຶງເອົາລາຍລະອຽດ Dailymotion ແລະຫຼິ້ນກັບເຄື່ອງຫຼິ້ນຝັງ Dailymotion.',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'ເລືອກບໍລິການທີ່ເປີດໃຊ້ແລ້ວວາງ URL ວິດີໂອສາທາລະນະ. PlayHub ຈະດຶງເອົາລາຍລະອຽດ ແລະຫຼິ້ນມັນຈາກຜູ້ໃຫ້ບໍລິການຕົ້ນສະບັບ.',
